select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%poly.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents vocaux et chat IA pour grandes entreprises qui traitent les appels de service client complexes : réservations, facturation, suivi de commandes et dépannage.', 'Enterprise AI voice and chat agents that handle complex customer service calls such as bookings, billing, order management and troubleshooting.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%juro.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme contractuelle IA dont les agents trient, analysent et annotent automatiquement vos contrats selon vos playbooks, extraient les données clés et les relient aux LLM via MCP.', 'AI contract platform whose agents triage, review and auto-redline contracts against custom playbooks, extract key data and connect contracts to LLMs via MCP.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%gradient-labs.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents IA pour les services financiers qui traitent le support client par téléphone, chat et e-mail et exécutent les procédures back-office : litiges, KYC et crédit.', 'AI agents for financial services that resolve customer support across voice, chat and email and run back-office procedures such as disputes, KYC and lending.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%v7labs.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''agents IA qui automatise le travail documentaire : extraction et analyse de contrats, dossiers et rapports pour les équipes finance, assurance et juridique.', 'AI agent platform that automates document-heavy work, extracting and reasoning over contracts, filings and reports for finance, insurance and legal teams.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%dext.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Automatisation comptable pour PME et cabinets qui extrait reçus, factures et relevés, avec un agent AI Assist qui prend en charge les tâches de tenue de comptes courantes.', 'Bookkeeping automation for SMBs and accountants that extracts receipts, invoices and statements, with an AI Assist agent handling everyday bookkeeping tasks.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%xelix.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA agentique pour les équipes fournisseurs qui rapproche les relevés fournisseurs, gère la boîte du helpdesk AP et signale les erreurs de facturation et les fraudes potentielles.', 'Agentic AI for accounts payable teams that reconciles supplier statements, runs the AP helpdesk inbox and flags invoice errors and potential fraud.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%moneypenny.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Réceptionniste IA qui répond à vos appels professionnels 24h/24, traite les questions fréquentes, prend les rendez-vous dans votre agenda et transfère les appels complexes à votre équipe ou à une réceptionniste.', 'AI receptionist that answers business calls 24/7, handles FAQs, books appointments in' || 'to your calendar and hands complex calls to your team or a human receptionist.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tessl.io%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Plateforme d''enablement qui fournit aux agents de code des skills et un contexte versionnés, et exécute evals et boucles automatisées de code review, scans de sécurité et test-and-fix.', 'Agent enablement platform that gives coding agents versioned skills and context, runs evals and automated loops for code review, security scans and test-and-fix.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%tortus.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'IA vocale ambiante pour les cliniciens du NHS et du privé qui enregistre les consultations, rédige notes cliniques et courriers et les renvoie dans le dossier patient informatisé.', 'Ambient voice AI for NHS and private clinicians that records consultations, drafts clinical notes and letters and writes them back in' || 'to the EHR.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%unitary.ai%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents virtuels IA qui exécutent les tâches opérationnelles répétitives directement dans vos outils existants pour assureurs, services financiers, santé et marketplaces, avec escalade vers des humains.', 'AI virtual agents that perform repetitive manual operations work inside existing tools for insurers, financial services, healthcare and marketplaces, escalating to humans.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.website ilike '%jacquard.com%' order by e.first_seen_at desc limit 1), 'fr', 'short_description', 'Agents marketing IA qui planifient, rédigent, contrôlent la conformité et optimisent vos contenus de marque pour e-mail, SMS, push, in-app, social payant et web, intégrés à vos ESP et CDP.', 'AI marketing agents that plan, write, compliance-check and optimise brand copy for email, SMS, push, in-app, paid social and web, integrated with ESPs and CDPs.');

select refresh_rankings();

-- Check: the new agents, with their page and French description
select e.name, e.slug as page, (t.value is not null) as french from entities e left join entity_i18n t on t.entity_id = e.id and t.lang = 'fr'
 where e.type = 'agent' and e.website ilike any (array['%landbot.io%', '%clientify.com%', '%lixsa.ai%', '%inmatic.ai%', '%gurusup.com%', '%doofinder.com%', '%aunoa.ai%', '%hubtype.com%', '%codacy.com%', '%visor.ai%', '%automaise.com%', '%agentifai.com%', '%fiz.co%', '%genieai.co%', '%poly.ai%', '%juro.com%', '%gradient-labs.ai%', '%v7labs.com%', '%dext.com%', '%xelix.com%', '%moneypenny.com%', '%tessl.io%', '%tortus.ai%', '%unitary.ai%', '%jacquard.com%']) order by e.name;
